INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist die Projektdefinition unabhängig von den Kundenanforderungen vollständig bestimmbar?', 2, '[{"text": "Nein", "correct": true, "because": "Kundenanforderungen bilden die Grundlage der Definition"}, {"text": "Ja", "correct": false, "because": "Ohne Anforderungen fehlt der Zweck"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine Projektdefinition ohne festgelegte Ziele als abgeschlossen gelten?', 2, '[{"text": "Nein", "correct": true, "because": "Ziele sind essenziell für die Orientierung"}, {"text": "Ja", "correct": false, "because": "Fehlende Ziele machen die Definition unbrauchbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss eine Projektdefinition zwingend alle technischen Details enthalten?', 2, '[{"text": "Nein", "correct": true, "because": "Technische Details folgen in der Planung"}, {"text": "Ja", "correct": false, "because": "Die Definition fokussiert auf Ziele und Rahmen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine unklare Projektdefinition die Zusammenarbeit im Team verbessern?', 2, '[{"text": "Nein", "correct": true, "because": "Unklarheit führt zu Missverständnissen"}, {"text": "Ja", "correct": false, "because": "Klarheit ist Voraussetzung für Koordination"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist es möglich, eine Projektdefinition nachträglich ohne Auswirkungen auf den Projektverlauf anzupassen?', 2, '[{"text": "Nein", "correct": true, "because": "Änderungen beeinflussen Planung und Ressourcen"}, {"text": "Ja", "correct": false, "because": "Anpassungen wirken sich immer aus"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Element ist in der Projektdefinition am wichtigsten, um den Projekterfolg zu sichern?', 3, '[{"text": "Klar formulierte Ziele", "correct": true, "because": "Ziele geben Richtung und Messbarkeit"}, {"text": "Detaillierte Kostenaufstellung", "correct": false, "because": "Wichtig, aber sekundär zur Zielsetzung"}, {"text": "Liste aller Teammitglieder", "correct": false, "because": "Relevanz entsteht später"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt der Projektdefinition hilft am meisten, Missverständnisse mit Stakeholdern zu vermeiden?', 2, '[{"text": "Abgestimmter Projektumfang", "correct": true, "because": "Definiert, was enthalten ist und was nicht"}, {"text": "Technische Machbarkeitsstudie", "correct": false, "because": "Folgt der Definition"}, {"text": "Zeitliche Meilensteine", "correct": false, "because": "Planungselement, nicht Definition"}]'),
('00000000-0000-0000-0000-000000000000', 'Was sollte primär in der Projektdefinition festgehalten werden, um die Erwartungen des Kunden zu erfüllen?', 3, '[{"text": "Ergebnisse und Lieferobjekte", "correct": true, "because": "Kunde fokussiert auf Endergebnisse"}, {"text": "Programmiersprachen", "correct": false, "because": "Technische Details sind zweitrangig"}, {"text": "Teamrollen", "correct": false, "because": "Interne Organisation, nicht Kundensicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Fehler in der Projektdefinition kann die Ressourcenplanung am stärksten beeinträchtigen?', 3, '[{"text": "Unklarer Projektumfang", "correct": true, "because": "Ohne Umfang sind Ressourcen schwer abschätzbar"}, {"text": "Fehlende Risikoanalyse", "correct": false, "because": "Wichtig, aber weniger direkt"}, {"text": "Unpräzise Teamzuweisung", "correct": false, "because": "Folgt der Definition"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Kriterium macht eine Projektdefinition messbar?', 2, '[{"text": "Konkrete Erfolgskriterien", "correct": true, "because": "Ermöglicht Überprüfung des Fortschritts"}, {"text": "Flexibilität der Ziele", "correct": false, "because": "Flexibilität erschwert Messbarkeit"}, {"text": "Anzahl der Projektphasen", "correct": false, "because": "Struktur, kein Messkriterium"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Bestandteile sollten in einer Projektdefinition enthalten sein?', 4, '[{"text": "Projektziele", "correct": true, "because": "Geben die Richtung vor"}, {"text": "Projektumfang", "correct": true, "because": "Definiert Grenzen"}, {"text": "Detaillierte Code-Struktur", "correct": false, "because": "Gehört zur Umsetzung"}, {"text": "Erfolgskriterien", "correct": true, "because": "Machen Erfolg überprüfbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken entstehen durch eine unzureichende Projektdefinition?', 3, '[{"text": "Scope Creep", "correct": true, "because": "Unklarer Umfang führt zu Ausweitung"}, {"text": "Überschreitung des Budgets", "correct": true, "because": "Fehlende Grenzen verteuern"}, {"text": "Schnellere Fertigstellung", "correct": false, "because": "Unklarheit verzögert"}, {"text": "Verzögerte Testphase", "correct": true, "because": "Unklare Ziele verschieben Tests"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Stakeholder sollten bei der Projektdefinition einbezogen werden?', 4, '[{"text": "Kunde", "correct": true, "because": "Definiert Anforderungen"}, {"text": "Projektteam", "correct": true, "because": "Kennt Machbarkeit"}, {"text": "Externe Lieferanten", "correct": false, "because": "Später relevant"}, {"text": "Projektleitung", "correct": true, "because": "Koordiniert und priorisiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren können die Qualität einer Projektdefinition beeinflussen?', 3, '[{"text": "Kommunikation mit Stakeholdern", "correct": true, "because": "Klarheit entsteht durch Abstimmung"}, {"text": "Verfügbarkeit von Entwicklern", "correct": false, "because": "Folgt der Definition"}, {"text": "Genauigkeit der Zielformulierung", "correct": true, "because": "Präzision ist entscheidend"}, {"text": "Realismus der Annahmen", "correct": true, "because": "Unrealistische Annahmen gefährden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine gut formulierte Projektdefinition?', 3, '[{"text": "Klarheit über Prioritäten", "correct": true, "because": "Fokus wird gesetzt"}, {"text": "Reduktion von Missverständnissen", "correct": true, "because": "Einheitliches Verständnis"}, {"text": "Automatische Fehlerkorrektur", "correct": false, "because": "Definition behebt keine Fehler"}, {"text": "Grundlage für Planung", "correct": true, "because": "Ermöglicht Strukturierung"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Die Projektdefinition dient als Basis für den Projektplan. b) Eine Projektdefinition muss alle Risiken im Detail analysieren.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Definition ist Grundlage, Risiken folgen später"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht zwingend"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine Projektdefinition sollte den Projektumfang eindeutig festlegen. b) Die Projektdefinition ist erst nach der Entwicklungsphase relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Umfang ist zentral, Definition ist früh nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Eine vage Projektdefinition kann zu höheren Kosten führen. b) Die Projektdefinition muss alle Meilensteine enthalten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Vagheit verteuert, Meilensteine sind Planung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Die Projektdefinition sollte Erfolgskriterien enthalten. b) Eine Projektdefinition ist nur für technische Projekte notwendig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kriterien sind essenziell, Definition ist allgemein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Eine Projektdefinition kann ohne Stakeholder-Abstimmung erstellt werden. b) Die Projektdefinition legt die Grundlage für die Ressourcenzuweisung.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Abstimmung ist nötig, Ressourcen folgen Definition"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]');

